//   (n52)-[:CALLS, via: "social_service::push_delivery::InMemoryNatsPublisher::new"]->(n24),
//   (n52)-[:CALLS, via: "social_service::push_delivery::InMemoryPushDlqRepository::new"]->(n34),
//   (n52)-[:CALLS, via: "social_service::push_delivery::NatsPushDispatcher::new"]->(n40),
//   (n52)-[:USES, via: "std::time::Duration::from_millis"]->(x3),
//   (n53)-[:CALLS, via: "social_service::push_delivery::DeliveryResultCode::from_i32"]->(n19),
//   (n54)-[:CALLS]->(n20),
